3D card showcase, pure black background, no black frames, no stutter. 16s, 1920x1080, SILENT. ALL animation via GSAP only — no CSS keyframes for the rock motion. GSAP controls the rotateY oscillation with yoyo:true repeat:-1. Cards always face camera. Shiny gloss uses CSS keyframes only for the gloss sweep (independent of card rotation). Name only below card
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;}
#scene{
position:relative;background:#000
display:flex;align-items:center;justify-content:center
}
card-stage{
position:absolute
display:flex;flex-direction:column;align-items:center
opacity:0
/* NO CSS animation here — GSAP controls everything */
}
card-wrap{
width:320px;height:460px;position:relative
/* initial 3D state set by GSAP */
}
card-face{
width:100%;height:100%
background:#fff;border-radius:6px
box-shadow:0 40px 80px rgba(0,0,0,0.85),0 6px 16px rgba(0,0,0,0.45)
overflow:hidden;position:relative
}
card-img{
width:calc(100% - 24px);height:calc(100% - 24px)
margin:12px;overflow:hidden;border-radius:3px;position:relative
}
card-img img{
width:100%;height:100%;object-fit:cover;display:block
filter:grayscale(10%) contrast(1.05)
}
/* gloss — pure CSS, independent loop, no conflict */
card-img::after{
content:""
position:absolute;left:-40%;top:10%
width:80%;padding-bottom:80%
border-radius:50%
background:radial-gradient(ellipse at center
rgba(255,255,255,0.28) 0%,rgba(255,255,255,0) 65%)
pointer-events:none
animation:gloss 2.4s ease-in-out infinite alternate
}
@keyframes gloss{
from{transform:translateX(0%);}
to  {transform:translateX(160%);}
}
role-label{
margin-top:24px;text-align:center
opacity:0
}
role-name{
font-family:'Playfair Display',Georgia,serif
font-size:46px;font-weight:700
color:#f0ece4;line-height:.90;letter-spacing:-.01em
}
#open-fade,#close-fade{
position:absolute;inset:0;z-index:50
background:#000;pointer-events:none
}
#open-fade{opacity:1;}
#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="scene">
<div id="open-fade"></div>
<div id="close-fade"></div>
<div class="card-stage" id="s1">
<div class="card-wrap" id="w1">
<div class="card-face"><div class="card-img"><img src="{{img1}}" alt=""></div></div>
</div>
<div class="role-label" id="l1"><div class="role-name">Alan Turing</div></div>
</div>
<div class="card-stage" id="s2">
<div class="card-wrap" id="w2">
<div class="card-face"><div class="card-img"><img src="{{img2}}" alt=""></div></div>
</div>
<div class="role-label" id="l2"><div class="role-name">Sherlock Holmes</div></div>
</div>
<div class="card-stage" id="s3">
<div class="card-wrap" id="w3">
<div class="card-face"><div class="card-img"><img src="{{img3}}" alt=""></div></div>
</div>
<div class="role-label" id="l3"><div class="role-name">Hamlet</div></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded', function(){
/* helper: start rock animation on a card-wrap element */
function startRock(el){
gsap.set(el, {transformPerspective:900, rotateX:6, rotateY:-20})
gsap.to(el, {
rotateY:20
rotateX:4
duration:1.2
ease:'sine.inOut'
repeat:-1
yoyo:true
})
}
/* pre-init all cards invisible and set 3D */
['#w1','#w2','#w3'].forEach(function(id){
gsap.set(id, {transformPerspective:900, rotateX:6, rotateY:-20})
})
var tl = gsap.timeline()
/* OPEN */
tl.to('#open-fade', {opacity:0, duration:0.45, ease:'power2.out'}, 0.0)
/* ── CARD 1 ── */
tl.set('#s1', {opacity:1}, 0.4)
tl.to('#s1', {scale:1, duration:0.6, ease:'back.out(1.2)'
startAt:{scale:0.82}}, 0.4)
tl.to('#l1', {opacity:1, y:0, duration:0.45, ease:'power3.out'
startAt:{y:12}}, 0.72)
tl.call(function(){ startRock(document.querySelector('#w1')); }, [], 0.4)
/* exit card 1 */
tl.to('#l1', {opacity:0, duration:0.3, ease:'power2.in'}, 4.4)
tl.to('#s1', {opacity:0, scale:0.84, duration:0.38, ease:'power2.in'}, 4.5)
tl.call(function(){ gsap.killTweensOf('#w1'); }, [], 4.9)
tl.set('#s1', {opacity:0}, 4.95)
/* ── CARD 2 ── */
tl.set('#s2', {opacity:1}, 4.9)
tl.to('#s2', {scale:1, duration:0.6, ease:'back.out(1.2)'
startAt:{scale:0.82}}, 4.9)
tl.to('#l2', {opacity:1, y:0, duration:0.45, ease:'power3.out'
startAt:{y:12}}, 5.22)
tl.call(function(){ startRock(document.querySelector('#w2')); }, [], 4.9)
tl.to('#l2', {opacity:0, duration:0.3, ease:'power2.in'}, 9.4)
tl.to('#s2', {opacity:0, scale:0.84, duration:0.38, ease:'power2.in'}, 9.5)
tl.call(function(){ gsap.killTweensOf('#w2'); }, [], 9.9)
tl.set('#s2', {opacity:0}, 9.95)
/* ── CARD 3 ── */
tl.set('#s3', {opacity:1}, 9.9)
tl.to('#s3', {scale:1, duration:0.6, ease:'back.out(1.2)'
startAt:{scale:0.82}}, 9.9)
tl.to('#l3', {opacity:1, y:0, duration:0.45, ease:'power3.out'
startAt:{y:12}}, 10.22)
tl.call(function(){ startRock(document.querySelector('#w3')); }, [], 9.9)
tl.to('#l3', {opacity:0, duration:0.3, ease:'power2.in'}, 14.5)
tl.to('#s3', {opacity:0, scale:0.84, duration:0.38, ease:'power2.in'}, 14.6)
/* CLOSE */
tl.to('#close-fade', {opacity:1, duration:0.65, ease:'power2.inOut'}, 14.75)
tl.set('#close-fade', {opacity:1}, 15.45)
})
</script>
</body>
</html>
```
